477	  /**
478	   * The YARN Router will forward to the respective YARN RM in which the AM is
479	   * running.
480	   *
481	   * Possible failures and behaviors:
482	   *
483	   * Client: identical behavior as {@code ClientRMService}.
484	   *
485	   * Router: the Client will timeout and resubmit the request.
486	   *
487	   * ResourceManager: the Router will timeout and the call will fail.
488	   *
489	   * State Store: the Router will timeout and it will retry depending on the
490	   * FederationFacade settings - if the failure happened before the select
491	   * operation.
492	   */
493	  @Override
494	  public KillApplicationResponse forceKillApplication(
495	      KillApplicationRequest request) throws YarnException, IOException {
496	
497	    long startTime = clock.getTime();
498	
499	    if (request == null || request.getApplicationId() == null) {
500	      routerMetrics.incrAppsFailedKilled();
501	      RouterServerUtil.logAndThrowException(
502	          "Missing forceKillApplication request or ApplicationId.", null);
503	    }
504	    ApplicationId applicationId = request.getApplicationId();
505	    SubClusterId subClusterId = null;
506	
507	    try {
508	      subClusterId = federationFacade
509	          .getApplicationHomeSubCluster(request.getApplicationId());
510	    } catch (YarnException e) {
511	      routerMetrics.incrAppsFailedKilled();
512	      RouterServerUtil.logAndThrowException("Application " + applicationId
513	          + " does not exist in FederationStateStore", e);
514	    }
515	
516	    ApplicationClientProtocol clientRMProxy =
517	        getClientRMProxyForSubCluster(subClusterId);
518	
519	    KillApplicationResponse response = null;
520	    try {
521	      LOG.info("forceKillApplication " + applicationId + " on SubCluster "
522	          + subClusterId);
523	      response = clientRMProxy.forceKillApplication(request);
524	    } catch (Exception e) {
525	      routerMetrics.incrAppsFailedKilled();
526	      LOG.error("Unable to kill the application report for "
527	          + request.getApplicationId() + "to SubCluster "
528	          + subClusterId.getId(), e);
529	      throw e;
530	    }
531	
532	    if (response == null) {
