608	  /**
609	   * The Yarn Router will forward the request to all the Yarn RMs in parallel,
610	   * after that it will group all the ApplicationReports by the ApplicationId.
611	   *
612	   * Possible failure:
613	   *
614	   * Client: identical behavior as {@code ClientRMService}.
615	   *
616	   * Router: the Client will timeout and resubmit the request.
617	   *
618	   * ResourceManager: the Router calls each Yarn RM in parallel. In case a
619	   * Yarn RM fails, a single call will timeout. However the Router will
620	   * merge the ApplicationReports it got, and provides a partial list to
621	   * the client.
622	   *
623	   * State Store: the Router will timeout and it will retry depending on the
624	   * FederationFacade settings - if the failure happened before the select
625	   * operation.
626	   */
627	  @Override
628	  public GetApplicationsResponse getApplications(GetApplicationsRequest request)
629	      throws YarnException, IOException {
630	    if (request == null) {
631	      routerMetrics.incrMultipleAppsFailedRetrieved();
632	      RouterServerUtil.logAndThrowException(
633	          "Missing getApplications request.",
634	          null);
635	    }
636	    long startTime = clock.getTime();
637	    Map<SubClusterId, SubClusterInfo> subclusters =
638	        federationFacade.getSubClusters(true);
639	    ClientMethod remoteMethod = new ClientMethod("getApplications",
640	        new Class[] {GetApplicationsRequest.class}, new Object[] {request});
641	    Map<SubClusterId, GetApplicationsResponse> applications;
642	
643	    try {
644	      applications = invokeConcurrent(subclusters.keySet(), remoteMethod,
645	          GetApplicationsResponse.class);
646	
647	    } catch (Exception ex) {
648	      routerMetrics.incrMultipleAppsFailedRetrieved();
649	      LOG.error("Unable to get applications due to exception.", ex);
650	      throw ex;
651	    }
652	    long stopTime = clock.getTime();
653	    routerMetrics.succeededMultipleAppsRetrieved(stopTime - startTime);
654	    // Merge the Application Reports
655	    return RouterYarnClientUtils.mergeApplications(applications.values(),
656	        returnPartialReport);
657	  }
