  /**
   * Merges a list of ReservationListResponse grouping by ReservationId.
   */
  public static ReservationListResponse mergeReservationsList(
      Collection<ReservationListResponse> responses) {
    // Check if only 1 sub cluster's reservations are not empty
    List<ReservationListResponse> notEmptyReservationResponse =
        responses.stream().filter(
        response -> (response != null &&
            !response.getReservationAllocationState().isEmpty()))
        .collect(Collectors.toList());
    if (notEmptyReservationResponse.size() == 1) {
      return notEmptyReservationResponse.get(0);
    }

    Map<ReservationId, ReservationAllocationState> reservationStates = new TreeMap<>();
    for (ReservationListResponse response : notEmptyReservationResponse) {
      List<ReservationAllocationState> reservationAllocationStates =
          response.getReservationAllocationState();
      if (reservationAllocationStates != null) {
        for (ReservationAllocationState reservationAllocationState : reservationAllocationStates) {
          reservationStates.put(reservationAllocationState.getReservationId(),
              reservationAllocationState);
        }
      }
    }
    return ReservationListResponse.newInstance(new ArrayList<>(reservationStates.values()));
  }

  public static GetQueueUserAclsInfoResponse mergeQueueUserAcls(
      Collection<GetQueueUserAclsInfoResponse> responses) {
    TreeMap<String, QueueUserACLInfo> map = new TreeMap<>();
    for (GetQueueUserAclsInfoResponse response : responses) {
      if (response != null && response.getUserAclsInfoList() != null) {
        for (QueueUserACLInfo queueUserACLInfo : response.getUserAclsInfoList()) {
          String queueName = queueUserACLInfo.getQueueName();
          QueueUserACLInfo queueUserACLInfoObj = map.getOrDefault(queueName, queueUserACLInfo);
          map.put(queueName, queueUserACLInfoObj);
        }
      }
    }
    return GetQueueUserAclsInfoResponse.newInstance(new ArrayList<>(map.values()));
  }

  public static GetAllResourceTypeInfoResponse mergeResourceTypeInfoResponse(
      Collection<GetAllResourceTypeInfoResponse> responses) {
    TreeMap<String, ResourceTypeInfo> resourceTypeInfoMap = new TreeMap<>();
    for (GetAllResourceTypeInfoResponse response : responses) {
      if (response != null && response.getResourceTypeInfo() != null) {
        List<ResourceTypeInfo> resourceTypeInfoList = response.getResourceTypeInfo();
        for (ResourceTypeInfo resourceTypeInfo : resourceTypeInfoList) {
          String resourceTypeName = resourceTypeInfo.getName();
          ResourceTypeInfo resourceTypeInfoObj =
              resourceTypeInfoMap.getOrDefault(resourceTypeName, resourceTypeInfo);
          resourceTypeInfoMap.put(resourceTypeName, resourceTypeInfoObj);
        }
      }
    }
    return GetAllResourceTypeInfoResponse.newInstance(
        new ArrayList<>(resourceTypeInfoMap.values()));
